// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 ethAmount) public {
        vm.assume(caller != address(0));
        // Ensure blacklist is false for caller
        vm.assume(!c.blacklist(caller));
        // Ensure distribution is not finished
        vm.assume(!c.distributionFinished());
        // Get initial totalRemaining before distribution
        uint256 initialRemaining = c.totalRemaining();
        // Ensure value is not zero and not exceeding remaining
        uint256 value = c.value();
        vm.assume(value > 0);
        vm.assume(value <= initialRemaining);
        // Provide enough ETH for the call
        vm.deal(caller, ethAmount);
        vm.prank(caller);
        c.getTokens();
        // Rule: totalRemaining should have decreased by value
        uint256 expected = initialRemaining - value;
        assertTrue(c.totalRemaining() == expected);
    }
}

